INSERT INTO public.products (
  generic_name,
  brand_name,
  manufacturer,
  strength,
  dosage_form,
  category,
  pack_size,
  nafdac_number,
  atc_code,
  requires_prescription,
  is_verified
)
SELECT
  source.generic_name,
  source.brand_name,
  source.manufacturer,
  source.strength,
  source.dosage_form,
  source.category,
  source.pack_size,
  source.nafdac_number,
  source.atc_code,
  source.requires_prescription,
  TRUE
FROM greenbook AS source
WHERE NOT EXISTS (
  SELECT 1
  FROM public.products AS existing
  WHERE LOWER(REGEXP_REPLACE(TRIM(COALESCE(existing.generic_name, '')), '\s+', '', 'g')) = LOWER(REGEXP_REPLACE(TRIM(COALESCE(source.generic_name, '')), '\s+', '', 'g'))
    AND LOWER(REGEXP_REPLACE(TRIM(COALESCE(existing.strength, '')), '\s+', '', 'g')) = LOWER(REGEXP_REPLACE(TRIM(COALESCE(source.strength, '')), '\s+', '', 'g'))
    AND LOWER(REGEXP_REPLACE(TRIM(COALESCE(existing.dosage_form, '')), '\s+', '', 'g')) = LOWER(REGEXP_REPLACE(TRIM(COALESCE(source.dosage_form, '')), '\s+', '', 'g'))
    AND LOWER(REGEXP_REPLACE(TRIM(COALESCE(existing.pack_size, '')), '\s+', '', 'g')) = LOWER(REGEXP_REPLACE(TRIM(COALESCE(source.pack_size, '')), '\s+', '', 'g'))
    AND LOWER(REGEXP_REPLACE(TRIM(COALESCE(existing.brand_name, '')), '\s+', '', 'g')) = LOWER(REGEXP_REPLACE(TRIM(COALESCE(source.brand_name, '')), '\s+', '', 'g'))
)
ON CONFLICT DO NOTHING;

COMMIT;
